// ===== CONFIGURAÇÃO =====
// Números autorizados (formato WAHA). Troque pelo seu número: DDI+DDD+número@c.us
const ALLOWED = ['5581999999999@c.us'];
// ========================
const input = $input.first().json;
const body = input.body || input;
const p = body.payload || {};

if (body.event !== 'message' || p.fromMe) return [];          // só mensagens recebidas
const chatId = p.from || '';
if (chatId.endsWith('@g.us')) return [];                       // ignora grupos
if (!ALLOWED.includes(chatId)) return [];                      // só números autorizados
const text = (p.body || '').trim();
if (!text) return [];                                          // ignora mídia sem texto

// Idempotência: o mesmo webhook (mesmo message id) não é processado duas vezes
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
const now = Date.now();
for (const k of Object.keys(sd.seen)) if (now - sd.seen[k] > 6 * 3600 * 1000) delete sd.seen[k];
if (sd.seen[p.id]) return [];
sd.seen[p.id] = now;

return [{ json: { chatId, text, messageId: p.id } }];
